-- ============================================================
-- Griya Zafira — Demo / seed data for every page
--
-- Every row here uses an id beginning with 5eed, so this data is easy to
-- spot and to remove: run seed_demo_data_remove.sql to delete all of it in
-- one go. Nothing outside the 5eed range is touched.
--
-- Dates are relative to current_date, so the dashboard's "7 hari terakhir"
-- chart and "bulan ini" figures always have data no matter when you run it.
--
-- Prerequisites: schema.sql, migrations 002-004, and
-- seed_siteplan_kaligangsa.sql (this references its units).
-- Safe to re-run.
-- ============================================================

on conflict (id) do nothing;

on conflict (id) do nothing;

update units set status='terjual' where unit_code in ('A1','A2','B3','D2','D9') and project_id=(select id from projects where name='Perumahan Zafira Permai Kaligangsa' limit 1);
update units set status='booking' where unit_code in ('B7','C5','E4','G3') and project_id=(select id from projects where name='Perumahan Zafira Permai Kaligangsa' limit 1);
update units set status='batal' where unit_code in ('F6') and project_id=(select id from projects where name='Perumahan Zafira Permai Kaligangsa' limit 1);

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (tanggal) do nothing;
